mapper.select:
SELECT EXISTS(
  SELECT 1
  FROM auth_beta_allowed_email
  WHERE email_normalized = #{emailNormalized}
)

SELECT FROM auth_beta_allowed_email allowed INNER JOIN auth_users creator ON creator.id = allowed.created_by LEFT JOIN auth_users registered ON registered.email_normalized = allowed.email_normalized
WHERE lower(allowed.email) LIKE concat('%', lower(#{keyword}), '%')
ORDER BY allowed.created_at DESC, allowed.id DESC LIMIT #{limit} OFFSET #{offset}
